CREATE DEFINER=`root`@`localhost` FUNCTION `make_system_user_id`(
    f_name VARCHAR(50),
    l_name VARCHAR(50)
) RETURNS varchar(50) CHARSET utf8mb3
    READS SQL DATA
BEGIN
    DECLARE base_id     VARCHAR(50);
    DECLARE max_userid  VARCHAR(50);
    DECLARE max_suffix  INT DEFAULT 0;
    DECLARE new_userid  VARCHAR(50);

    -- Build base prefix (first 2 letters of first name + first 4 of last name)
    SET base_id = CONCAT(
        LOWER(LEFT(f_name, 2)),
        LOWER(LEFT(l_name, 4))
    );

    
    -- Instructor logic:
    -- Get the highest userid starting with this base prefix.
    -- Example:
    -- dejohns09
    -- dejohns10   ← highest
    
		SELECT system_user_id
        INTO max_userid
        FROM people
        WHERE system_user_id LIKE CONCAT(base_id, '%')
        ORDER BY system_user_id DESC
        LIMIT 1;

   
    -- Extract numeric suffix and increment it
 
    IF max_userid IS NULL THEN
        SET max_suffix = 1;
    ELSE
        SET max_suffix = CAST(
            SUBSTRING(max_userid, LENGTH(base_id) + 1)
            AS UNSIGNED
        ) + 1;
    END IF;

  
    -- Build final userid (prefix + 2-digit number)

    SET new_userid = CONCAT(base_id, LPAD(max_suffix, 2, '0'));

    RETURN new_userid;
END ;;
DELIMITER ;
